-- Privacy-first private albums shared only with active Matches. These are media objects, not chat history.
create table if not exists public.private_albums(
  id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null check(char_length(trim(title)) between 1 and 60),status text not null default 'active' check(status in('active','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.private_album_grants(
  album_id uuid not null references public.private_albums(id) on delete cascade,viewer_id uuid not null references auth.users(id) on delete cascade,granted_at timestamptz not null default now(),expires_at timestamptz,revoked_at timestamptz,primary key(album_id,viewer_id)
);
create table if not exists public.private_album_items(
  id uuid primary key default gen_random_uuid(),album_id uuid not null references public.private_albums(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,storage_path text not null unique,media_type text not null check(media_type in('image','video')),moderation_status text not null default 'pending' check(moderation_status in('pending','approved','rejected','removed')),max_views smallint check(max_views is null or max_views between 1 and 10),expires_at timestamptz,created_at timestamptz not null default now()
);
create table if not exists public.private_album_views(
  item_id uuid not null references public.private_album_items(id) on delete cascade,viewer_id uuid not null references auth.users(id) on delete cascade,view_count integer not null default 0,last_view_at timestamptz,primary key(item_id,viewer_id)
);
create table if not exists public.private_album_upload_intents(
  id uuid primary key default gen_random_uuid(),album_id uuid not null references public.private_albums(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,storage_path text not null unique,mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 52428800),status text not null default 'created' check(status in('created','consumed','cancelled','expired')),expires_at timestamptz not null default(now()+interval '2 hours'),created_at timestamptz not null default now(),consumed_at timestamptz
);
create index if not exists private_album_grants_viewer_idx on public.private_album_grants(viewer_id,expires_at);
create index if not exists private_album_items_album_idx on public.private_album_items(album_id,created_at desc);

alter table public.private_albums enable row level security;alter table public.private_album_grants enable row level security;alter table public.private_album_items enable row level security;alter table public.private_album_views enable row level security;alter table public.private_album_upload_intents enable row level security;
revoke insert,update,delete on public.private_albums,public.private_album_grants,public.private_album_items,public.private_album_views,public.private_album_upload_intents from authenticated,anon;
revoke select on public.private_albums,public.private_album_grants,public.private_album_items,public.private_album_views,public.private_album_upload_intents from authenticated,anon;

create or replace function public.is_active_match_pair(a uuid,b uuid) returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from public.matches m where m.status='active' and ((m.user_a=a and m.user_b=b) or(m.user_a=b and m.user_b=a))) and not exists(select 1 from public.blocks x where (x.blocker_id=a and x.blocked_id=b) or(x.blocker_id=b and x.blocked_id=a));$$;
create or replace function public.can_view_private_album(p_album uuid,p_viewer uuid) returns boolean language sql security definer stable set search_path=public as $$select exists(select 1 from public.private_albums a where a.id=p_album and a.status='active' and (a.owner_id=p_viewer or exists(select 1 from public.private_album_grants g where g.album_id=a.id and g.viewer_id=p_viewer and g.revoked_at is null and(g.expires_at is null or g.expires_at>now()) and public.is_active_match_pair(a.owner_id,p_viewer))));$$;
revoke all on function public.is_active_match_pair(uuid,uuid),public.can_view_private_album(uuid,uuid) from public,anon;
grant execute on function public.can_view_private_album(uuid,uuid) to authenticated;

create or replace function public.create_private_album(p_title text) returns uuid language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();r uuid;begin if u is null then raise exception'not_authenticated';end if;if char_length(trim(p_title)) not between 1 and 60 then raise exception'invalid_title';end if;insert into public.private_albums(owner_id,title)values(u,trim(p_title))returning id into r;return r;end;$$;
create or replace function public.grant_private_album(p_album uuid,p_viewer uuid,p_expires_hours integer default 24) returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();begin if u is null then raise exception'not_authenticated';end if;if not exists(select 1 from public.private_albums where id=p_album and owner_id=u and status='active')then raise exception'album_unavailable';end if;if not public.is_active_match_pair(u,p_viewer)then raise exception'active_match_required';end if;if p_expires_hours<1 or p_expires_hours>720 then raise exception'invalid_expiry';end if;insert into public.private_album_grants(album_id,viewer_id,expires_at,revoked_at)values(p_album,p_viewer,now()+make_interval(hours=>p_expires_hours),null)on conflict(album_id,viewer_id)do update set granted_at=now(),expires_at=excluded.expires_at,revoked_at=null;return jsonb_build_object('ok',true);end;$$;
create or replace function public.revoke_private_album(p_album uuid,p_viewer uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();begin if u is null then raise exception'not_authenticated';end if;if not exists(select 1 from public.private_albums where id=p_album and owner_id=u)then raise exception'forbidden';end if;update public.private_album_grants set revoked_at=now() where album_id=p_album and viewer_id=p_viewer;return jsonb_build_object('ok',true);end;$$;

create or replace function public.create_private_album_upload(p_album uuid,p_mime text,p_size bigint) returns table(intent_id uuid,storage_path text,expires_at timestamptz) language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();i uuid:=gen_random_uuid();path text;begin if u is null then raise exception'not_authenticated';end if;if not exists(select 1 from public.private_albums where id=p_album and owner_id=u and status='active')then raise exception'album_unavailable';end if;if p_mime not in('image/jpeg','image/png','image/webp','video/mp4','video/webm')then raise exception'invalid_mime';end if;if p_size<1 or p_size>52428800 or(p_mime like'image/%' and p_size>8388608)then raise exception'file_too_large';end if;path:=u::text||'/'||p_album::text||'/'||i::text||'.raw';insert into public.private_album_upload_intents(id,album_id,user_id,storage_path,mime_type,size_bytes)values(i,p_album,u,path,p_mime,p_size);return query select i,path,now()+interval'2 hours';end;$$;
create or replace function public.finalize_private_album_upload(p_intent uuid,p_final_path text,p_status text,p_max_views integer default null,p_expires_hours integer default 24) returns uuid language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();i public.private_album_upload_intents%rowtype;item uuid;kind text;begin if u is null then raise exception'not_authenticated';end if;select*into i from public.private_album_upload_intents where id=p_intent and user_id=u and status='created' and expires_at>now() for update;if not found then raise exception'intent_unavailable';end if;if p_status not in('pending','approved','rejected')then raise exception'invalid_status';end if;if p_max_views is not null and(p_max_views<1 or p_max_views>10)then raise exception'invalid_views';end if;if p_expires_hours<1 or p_expires_hours>720 then raise exception'invalid_expiry';end if;kind:=case when i.mime_type like'image/%' then'image' else'video'end;insert into public.private_album_items(album_id,owner_id,storage_path,media_type,moderation_status,max_views,expires_at)values(i.album_id,u,p_final_path,kind,p_status,p_max_views,now()+make_interval(hours=>p_expires_hours))returning id into item;update public.private_album_upload_intents set status='consumed',consumed_at=now()where id=i.id;return item;end;$$;

create or replace function public.get_private_albums() returns table(album_id uuid,title text,is_owner boolean,owner_id uuid,owner_name text,expires_at timestamptz,item_count bigint) language plpgsql security definer stable set search_path=public as $$declare u uuid:=auth.uid();begin if u is null then raise exception'not_authenticated';end if;return query select a.id,a.title,a.owner_id=u,a.owner_id,p.display_name,g.expires_at,(select count(*)from public.private_album_items i where i.album_id=a.id and i.moderation_status='approved' and(i.expires_at is null or i.expires_at>now())) from public.private_albums a join public.profiles p on p.id=a.owner_id left join public.private_album_grants g on g.album_id=a.id and g.viewer_id=u where a.status='active' and(a.owner_id=u or(g.revoked_at is null and(g.expires_at is null or g.expires_at>now())and public.is_active_match_pair(a.owner_id,u))) order by(a.owner_id=u)desc,a.updated_at desc;end;$$;
create or replace function public.get_private_album_items(p_album uuid) returns table(item_id uuid,media_type text,moderation_status text,max_views smallint,expires_at timestamptz,remaining_views integer,created_at timestamptz) language plpgsql security definer stable set search_path=public as $$declare u uuid:=auth.uid();owner uuid;begin if u is null then raise exception'not_authenticated';end if;if not public.can_view_private_album(p_album,u)then raise exception'forbidden';end if;select owner_id into owner from public.private_albums where id=p_album;return query select i.id,i.media_type,i.moderation_status,i.max_views,i.expires_at,case when owner=u or i.max_views is null then null else greatest(i.max_views-coalesce(v.view_count,0),0)end,i.created_at from public.private_album_items i left join public.private_album_views v on v.item_id=i.id and v.viewer_id=u where i.album_id=p_album and(owner=u or(i.moderation_status='approved'and(i.expires_at is null or i.expires_at>now())and(i.max_views is null or coalesce(v.view_count,0)<i.max_views))) order by i.created_at;end;$$;
create or replace function public.consume_private_album_item(p_item uuid) returns table(storage_path text,media_type text) language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();i public.private_album_items%rowtype;owner boolean;v integer;begin if u is null then raise exception'not_authenticated';end if;select*into i from public.private_album_items where id=p_item;if not found or not public.can_view_private_album(i.album_id,u)then raise exception'forbidden';end if;owner:=i.owner_id=u;if not owner and(i.moderation_status<>'approved'or(i.expires_at is not null and i.expires_at<=now()))then raise exception'item_unavailable';end if;if not owner and i.max_views is not null then select coalesce(view_count,0)into v from public.private_album_views where item_id=i.id and viewer_id=u;if coalesce(v,0)>=i.max_views then raise exception'view_limit_reached';end if;insert into public.private_album_views(item_id,viewer_id,view_count,last_view_at)values(i.id,u,1,now())on conflict(item_id,viewer_id)do update set view_count=public.private_album_views.view_count+1,last_view_at=now();end if;return query select i.storage_path,i.media_type;end;$$;

revoke all on function public.create_private_album(text),public.grant_private_album(uuid,uuid,integer),public.revoke_private_album(uuid,uuid),public.create_private_album_upload(uuid,text,bigint),public.finalize_private_album_upload(uuid,text,text,integer,integer),public.get_private_albums(),public.get_private_album_items(uuid),public.consume_private_album_item(uuid) from public,anon;
grant execute on function public.create_private_album(text),public.grant_private_album(uuid,uuid,integer),public.revoke_private_album(uuid,uuid),public.create_private_album_upload(uuid,text,bigint),public.finalize_private_album_upload(uuid,text,text,integer,integer),public.get_private_albums(),public.get_private_album_items(uuid),public.consume_private_album_item(uuid) to authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('private-albums','private-albums',false,52428800,array['image/jpeg','image/png','image/webp','video/mp4','video/webm'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists private_albums_insert_owner on storage.objects;create policy private_albums_insert_owner on storage.objects for insert to authenticated with check(bucket_id='private-albums'and split_part(name,'/',1)=auth.uid()::text);
drop policy if exists private_albums_select_authorized on storage.objects;create policy private_albums_select_authorized on storage.objects for select to authenticated using(bucket_id='private-albums'and(split_part(name,'/',1)=auth.uid()::text or exists(select 1 from public.private_album_items i where i.storage_path=name and i.moderation_status='approved'and public.can_view_private_album(i.album_id,auth.uid()))));
drop policy if exists private_albums_delete_owner on storage.objects;create policy private_albums_delete_owner on storage.objects for delete to authenticated using(bucket_id='private-albums'and split_part(name,'/',1)=auth.uid()::text);
